Assuming the usual includes and using namespace std, what does this program print?

struct Box {
  Box() {}
  Box(const Box&) { cout << 'C'; }
  Box(Box&&) { cout << 'M'; }
};
int main() { Box a; Box b = a; Box c = std::move(a); }

Assuming the usual includes and using namespace std, what does this program print?

struct W {
  W() { cout << 'A'; }
  W(int n) : W() { cout << 'B'; }
};
int main() { W w(5); }

Assuming the usual includes and using namespace std, what does this program print?

struct A { ~A() { cout << 'a'; } };
struct B { A m; B() { throw 1; } ~B() { cout << 'b'; } };
int main() { try { B x; } catch (...) { cout << 'c'; } }
